/**
 * Render the user's skill-readiness radar on the profile page.
 * Hand-rendered SVG (no Chart.js).
 *
 * @module     local_airpay_users/skill_radar
 * @copyright  2026 Airpay Payment Services
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
define("local_airpay_users/skill_radar", [], function() {
    "use strict";

    var polarPoint = function(cx, cy, radius, angleRad) {
        return [
            cx + radius * Math.cos(angleRad - Math.PI / 2),
            cy + radius * Math.sin(angleRad - Math.PI / 2)
        ];
    };

    var renderRadar = function(canvas) {
        var labels, current, required;
        try {
            labels = JSON.parse(canvas.dataset.radarLabels || "[]");
            current = JSON.parse(canvas.dataset.radarCurrent || "[]");
            required = JSON.parse(canvas.dataset.radarRequired || "[]");
        } catch (e) {
            return;
        }
        if (!labels.length || labels.length !== current.length
            || labels.length !== required.length) return;

        var size = 280;
        var cx = size / 2;
        var cy = size / 2;
        var r = (size / 2) - 30;
        var max = Math.max(5);
        for (var i = 0; i < labels.length; i++) {
            if (required[i] > max) max = required[i];
            if (current[i] > max) max = current[i];
        }
        var ns = "http://www.w3.org/2000/svg";

        var svg = document.createElementNS(ns, "svg");
        svg.setAttribute("width",  String(size));
        svg.setAttribute("height", String(size));
        svg.setAttribute("viewBox", "0 0 " + size + " " + size);
        svg.setAttribute("role", "img");

        var title = document.createElementNS(ns, "title");
        title.textContent = "Skill readiness radar";
        svg.appendChild(title);
        var desc = document.createElementNS(ns, "desc");
        var descParts = [];
        for (var j = 0; j < labels.length; j++) {
            descParts.push(labels[j] + ": " + current[j] + " of " + required[j]);
        }
        desc.textContent = descParts.join(". ") + ".";
        svg.appendChild(desc);

        // Concentric grid rings.
        for (var lvl = 1; lvl <= max; lvl++) {
            var ring = document.createElementNS(ns, "polygon");
            var ringPoints = labels.map(function(_, k) {
                var a = (k / labels.length) * 2 * Math.PI;
                var p = polarPoint(cx, cy, (lvl / max) * r, a);
                return p[0].toFixed(1) + "," + p[1].toFixed(1);
            }).join(" ");
            ring.setAttribute("points", ringPoints);
            ring.setAttribute("fill", "none");
            ring.setAttribute("stroke", "#e2e6ef");
            ring.setAttribute("stroke-width", "1");
            svg.appendChild(ring);
        }

        // Axis lines + labels.
        labels.forEach(function(label, k) {
            var a = (k / labels.length) * 2 * Math.PI;
            var p = polarPoint(cx, cy, r, a);
            var line = document.createElementNS(ns, "line");
            line.setAttribute("x1", String(cx));
            line.setAttribute("y1", String(cy));
            line.setAttribute("x2", p[0].toFixed(1));
            line.setAttribute("y2", p[1].toFixed(1));
            line.setAttribute("stroke", "#e2e6ef");
            line.setAttribute("stroke-width", "1");
            svg.appendChild(line);

            var lp = polarPoint(cx, cy, r + 14, a);
            var text = document.createElementNS(ns, "text");
            text.setAttribute("x", lp[0].toFixed(1));
            text.setAttribute("y", lp[1].toFixed(1));
            text.setAttribute("text-anchor", "middle");
            text.setAttribute("dominant-baseline", "middle");
            text.setAttribute("font-size", "10");
            text.setAttribute("fill", "#5a6070");
            var trimmed = label.length > 20 ? label.slice(0, 18) + "…" : label;
            text.textContent = trimmed;
            svg.appendChild(text);
        });

        // Required (target) — dashed teal.
        var requiredPoints = labels.map(function(_, k) {
            var a = (k / labels.length) * 2 * Math.PI;
            var p = polarPoint(cx, cy, (required[k] / max) * r, a);
            return p[0].toFixed(1) + "," + p[1].toFixed(1);
        }).join(" ");
        var reqPoly = document.createElementNS(ns, "polygon");
        reqPoly.setAttribute("points", requiredPoints);
        reqPoly.setAttribute("fill", "none");
        reqPoly.setAttribute("stroke", "#0f7a73");
        reqPoly.setAttribute("stroke-width", "1.5");
        reqPoly.setAttribute("stroke-dasharray", "4 3");
        svg.appendChild(reqPoly);

        // Current — solid blue with low-opacity fill.
        var currentPoints = labels.map(function(_, k) {
            var a = (k / labels.length) * 2 * Math.PI;
            var p = polarPoint(cx, cy, (current[k] / max) * r, a);
            return p[0].toFixed(1) + "," + p[1].toFixed(1);
        }).join(" ");
        var curPoly = document.createElementNS(ns, "polygon");
        curPoly.setAttribute("points", currentPoints);
        curPoly.setAttribute("fill", "rgba(0,102,167,0.15)");
        curPoly.setAttribute("stroke", "#0066A7");
        curPoly.setAttribute("stroke-width", "2");
        svg.appendChild(curPoly);

        canvas.replaceWith(svg);
    };

    return {
        init: function() {
            var canvas = document.getElementById("ap-skills-radar-canvas");
            if (!canvas) return;
            renderRadar(canvas);
        }
    };
});
